import {componentDefinitions} from './scene-components.js';
import {prefabRootFor,prefabInstanceChanges} from './prefab-instances.js';
export function prefabInstanceMarkup(object,objects,{esc,icon,running}){const root=prefabRootFor(objects,object);if(!root)return '';const changes=prefabInstanceChanges(objects,root),labelFor=c=>{const owner=objects.find(o=>o.prefabRoot===root.id&&o.prefabLocalId===c.object)||root.prefabLink.baseline.find(o=>o.id===c.object);let path=c.path;if(path[0]==='components'){const component=owner?.components?.find(v=>v.id===path[1]);path=[component?.name||component?.type||'컴포넌트',...path.slice(2).filter(k=>k!=='properties').map(k=>componentDefinitions[component?.type]?.properties[k]?.label||k)];}else path=path.map((k,i)=>i===0?({position:'위치',rotation:'회전',scale:'크기',materialSurface:'머테리얼',color:'색상',name:'이름',visible:'표시'}[k]||k):typeof k==='number'?['X','Y','Z'][k]||k:k);return (owner?.name||c.object)+' · '+(path.length?path.join(' · '):(c.deleted?'오브젝트 삭제':'오브젝트 추가'));},disabled=running?' disabled':'';return `<section class="component-section prefab-instance"><h3>${icon('cube')}프리팹</h3><button class="asset-open-link" data-prefab-op="open"${disabled}>${icon('external')}${esc(root.prefabAsset.split('/').at(-1).replace('.hbprefab.json',''))}</button><div class="prefab-actions"><button data-prefab-op="refresh"${disabled}>동기화</button><button data-prefab-op="adopt"${disabled}>자식 변경 포함</button><button data-prefab-op="apply-all"${disabled}>모두 적용</button><button data-prefab-op="revert-all"${disabled}>모두 복원</button><button data-prefab-op="unpack"${disabled}>연결 해제</button></div><details ${changes.length?'open':''}><summary>변경 ${changes.length}개${root.prefabLink.conflicts.length?' · 충돌 '+root.prefabLink.conflicts.length+'개':''}</summary>${changes.map((c,i)=>{const conflict=root.prefabLink.conflicts.find(r=>r.object===c.object&&JSON.stringify(r.path)===JSON.stringify(c.path)),label=labelFor(c);return `<div data-prefab-property="${esc(c.path.join('.'))}" class="prefab-property-row${conflict?' conflict':''}"><span title="${esc(conflict?'원본: '+JSON.stringify(conflict.source)+' / 인스턴스: '+JSON.stringify(c.value):label)}">${esc(label)}</span>${`<button data-prefab-op="revert" data-prefab-change="${i}" aria-label="${esc(label)} 복원"${disabled}>복원</button><button data-prefab-op="apply" data-prefab-change="${i}" aria-label="${esc(label)} 적용"${disabled}>적용</button>`}</div>`;}).join('')}</details></section>`;}
